    public SrsReportEMailDataContract parmEMailContract(SrsReportEMailDataContract _emailContract)
    {
        next parmEMailContract(_emailContract);

        emailContract = _emailContract;
        
        if (!emailContract)
        {
            emailContract = new SrsReportEMailDataContract();
            emailContract.parmAttachmentFileFormat(this.emailAttachmentFileFormat());
            emailContract.parmAttachmentImageFileFormat(this.emailAttachmentImageFileFormat());
            emailContract.parmCc(this.emailCc());
            if(this.emailTo())
            {
                emailContract.parmTo(this.emailTo());
                emailContract.parmSubject(this.emailSubject());
            }
            else
            {
                 emailContract.parmTo(CustFormletterDocument::find().METUnsentFTIEmailTo);
                 emailContract.parmSubject("@KPMGAddOn:InvalidFTIEmail" + ': ');
            }
            
        }       

        return emailContract;
    }
